ON CONFLICT (project_id) DO UPDATE SET
  start_latitude = EXCLUDED.start_latitude,
  start_longitude = EXCLUDED.start_longitude,
  end_latitude = EXCLUDED.end_latitude,
  end_longitude = EXCLUDED.end_longitude,
  route_points = EXCLUDED.route_points,
  route_source = EXCLUDED.route_source,
  route_quality = EXCLUDED.route_quality,
  declared_length_km = EXCLUDED.declared_length_km,
  mapped_length_km = EXCLUDED.mapped_length_km,
  updated_at = now();

-- Barangay attribution, from the surveyed road name rather than a regex over
-- free-text location. Also mirrors start/end onto fmr_projects for the older
-- views that read it directly.
UPDATE public.fmr_projects AS p SET
  barangay = v.barangay,
  barangay_end = v.barangay_end,
  inventory_road_name = v.inventory_road_name,
  length_conflict = v.length_conflict
